"""
MXFP4 MoE — Phase 2: Remote aiter introspection.

Dumps aiter CK kernel configs, CSV tuning data, importable symbols from
fused_moe, and shape info to stderr. Delegates to ref_kernel for correctness.
Zero risk — all computation is done by the reference implementation.
"""
import sys
import os
import inspect
from task import input_t, output_t
from reference import ref_kernel


def custom_kernel(data: input_t) -> output_t:
    (
        hidden_states, gate_up_weight, down_weight,
        gate_up_weight_scale, down_weight_scale,
        gate_up_weight_shuffled, down_weight_shuffled,
        gate_up_weight_scale_shuffled, down_weight_scale_shuffled,
        topk_weights, topk_ids, config,
    ) = data

    M = hidden_states.shape[0]
    E = gate_up_weight_shuffled.shape[0]
    print(f"INTROSPECT: M={M}, E={E}, config={config}", file=sys.stderr)

    # Dump fused_moe module symbols
    try:
        import aiter.fused_moe as fm
        symbols = [s for s in dir(fm) if not s.startswith('_')]
        print(f"FUSED_MOE_SYMBOLS: {symbols}", file=sys.stderr)

        # Check for stage kernel functions
        for name in ['ck_moe_stage1', 'ck_moe_stage2', 'moe_sorting_fwd',
                      'moe_sorting_opus_fwd', 'get_2stage_cfgs',
                      'ck_moe_2stages', 'fused_moe_a4w4']:
            if hasattr(fm, name):
                obj = getattr(fm, name)
                try:
                    sig = inspect.signature(obj)
                    print(f"FOUND: {name}{sig}", file=sys.stderr)
                except (ValueError, TypeError):
                    print(f"FOUND: {name} (no sig)", file=sys.stderr)
            else:
                print(f"MISSING: {name}", file=sys.stderr)
    except Exception as e:
        print(f"FUSED_MOE_INSPECT_ERR: {e}", file=sys.stderr)

    # Dump aiter configs directory
    try:
        import aiter
        aiter_path = os.path.dirname(aiter.__file__)
        csv_path = os.path.join(aiter_path, "configs")
        if os.path.isdir(csv_path):
            for f in sorted(os.listdir(csv_path)):
                fpath = os.path.join(csv_path, f)
                if f.endswith('.csv'):
                    print(f"CSV: {f}", file=sys.stderr)
                    with open(fpath) as fh:
                        for i, line in enumerate(fh):
                            if i < 5:
                                print(f"  {line.rstrip()}", file=sys.stderr)
        else:
            print(f"NO_CSV_DIR: {csv_path}", file=sys.stderr)
            # Try to find configs elsewhere
            for root, dirs, files in os.walk(aiter_path):
                for f in files:
                    if f.endswith('.csv'):
                        print(f"FOUND_CSV: {os.path.join(root, f)}", file=sys.stderr)
    except Exception as e:
        print(f"CSV_ERR: {e}", file=sys.stderr)

    # Check what CK kernels are available
    try:
        from aiter.fused_moe import get_2stage_cfgs
        cfgs = get_2stage_cfgs()
        print(f"2STAGE_CFGS: {cfgs}", file=sys.stderr)
    except Exception as e:
        print(f"2STAGE_CFGS_ERR: {e}", file=sys.stderr)

    return ref_kernel(data)

